fn bind_keys(cx: &mut App) {
    static BOUND: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
    if BOUND.swap(true, std::sync::atomic::Ordering::SeqCst) {
        return;
    }
    // Not while typing in the search or name fields.
    let items = Some("MediaPool && !Input");
    cx.bind_keys([
        KeyBinding::new("delete", RemoveSelected, items),
        KeyBinding::new("backspace", RemoveSelected, items),
        KeyBinding::new("space", PlaySelected, items),
        KeyBinding::new("enter", OpenSelected, items),
        KeyBinding::new("/", FocusSearch, items),
        KeyBinding::new("cmd-a", SelectAll, items),
        KeyBinding::new("ctrl-a", SelectAll, items),
        KeyBinding::new("left", SelectPrev, items),
        KeyBinding::new("right", SelectNext, items),
        KeyBinding::new("up", SelectUp, items),
        KeyBinding::new("down", SelectDown, items),
        KeyBinding::new("escape", Deselect, items),
        KeyBinding::new(",", InsertSelected, items),
        KeyBinding::new("f2", RenameSelected, items),
        KeyBinding::new("cmd-up", OpenParentBin, items),
        KeyBinding::new("ctrl-up", OpenParentBin, items),
        KeyBinding::new("i", MarkSourceIn, items),
        KeyBinding::new("o", MarkSourceOut, items),
        KeyBinding::new(".", OverwriteSelected, items),
    ]);
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Layout {
    Grid,
    List,
}

pub struct MediaPoolPanel {
    state: Entity<EditorState>,
    focus: FocusHandle,
    search: Entity<InputState>,
    bin_input: Entity<InputState>,
    /// The item being renamed and its name field.
    renaming_item: Option<MediaId>,
    item_input: Entity<InputState>,
    layout: Layout,
    /// The bin open in the pool; `None` is the top level.
    bin: Option<BinId>,
    renaming: Option<BinId>,
    /// The selected items and folders, and the cursor.
    sel: Selection,
    thumbs: Thumbs,
    jobs: Vec<JobStatus>,
    /// Proxy creation progress, written from background threads.
    proxies: Arc<Mutex<HashMap<MediaId, f32>>>,
    /// Proxy builds started this session, by path (see `hdr.rs`).
    hdr_proxies: HashMap<PathBuf, hdr::Tried>,
    /// Files dragged in from outside, while they are over the items.
    dropping: Option<Vec<PathBuf>>,
    /// The items area last frame, for the grid's columns and for keeping
    /// the selection in view.
    area: Rc<Cell<Bounds<Pixels>>>,
    /// The grid's columns last frame, for moving up and down.
    cols: Cell<u16>,
    scroll: ScrollHandle,
    /// Scroll the selected item into view when it next paints.
    reveal: Rc<Cell<bool>>,
    /// The selection in pool order, when it is more than one item: what
    /// grabbing one of them drags.
    dragged: Vec<MediaId>,
    /// The video tile the pointer skims, and where across it, 0..1.
    skim: Option<(MediaId, f32)>,
    /// Where each item (`Some`) and folder (`None`) painted last frame,
    /// for the rubber band.
    placed: Rc<RefCell<Vec<Placed>>>,
    /// A rubber band being dragged across empty space.
    band: Option<Band>,
    _subscriptions: Vec<Subscription>,
    _poll: Task<()>,
}

impl MediaPoolPanel {
    pub fn new(state: Entity<EditorState>, window: &mut Window, cx: &mut Context<Self>) -> Self {
        bind_keys(cx);
        let search = cx.new(|cx| InputState::new(window, cx).placeholder("Search media"));
        let bin_input = cx.new(|cx| InputState::new(window, cx));
        let item_input = cx.new(|cx| InputState::new(window, cx));
        let _subscriptions = vec![
            cx.observe(&state, |_, _, cx| cx.notify()),
            cx.subscribe(&search, |_, _, _: &InputEvent, cx| cx.notify()),
            cx.subscribe_in(&item_input, window, |this, input, ev, window, cx| {
                if matches!(ev, InputEvent::PressEnter { .. } | InputEvent::Blur) {
                    let name = input.read(cx).value().trim().to_owned();
                    this.finish_item_rename(name, window, cx);
                }
            }),
            cx.subscribe_in(&bin_input, window, |this, input, ev, _, cx| {
                if matches!(ev, InputEvent::PressEnter { .. } | InputEvent::Blur) {
                    let name = input.read(cx).value().trim().to_owned();
                    this.finish_rename(name, cx);
                }
            }),
        ];
        let _poll = cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor().timer(POLL).await;
                if this.update(cx, |this, cx| this.poll(cx)).is_err() {
                    break;
                }
            }
        });
        let mut sel = Selection::default();
        if crate::demo::enabled()
            && let Some(first) = state.read(cx).bus.project().media.first()
        {
            sel.set(&[Entry::Media(first.id)]);
        }
        if let Some(form) = crate::demo::generate_form() {
            cx.defer_in(window, move |this: &mut Self, window, cx| {
                match form.as_str() {
                    "voiceover" => this.open_voiceover(None, window, cx),
                    "voices" | "voices-describe" | "voices-audio" => {
                        let start = match form.as_str() {
                            "voices-describe" => crate::ui::voices::Start::Describe {
                                description: String::new(),
                            },
                            "voices-audio" => crate::ui::voices::Start::Clone {
                                files: Vec::new(),
                                name: String::new(),
                            },
                            _ => crate::ui::voices::Start::Find,
                        };
                        crate::ui::voices::open(this.state.clone(), start, None, window, cx)
                    }
                    "sfx" => this.open_generate(generate::Kind::SoundEffect, window, cx),
                    "image" => {
                        // Without a provider set, the first model fal offers.
                        let model = this.image_model(cx).or_else(|| {
                            let fal = flikk_cloud::provider("fal")?;
                            let first =
                                fal.offer(flikk_core::cloud::Capability::Image)?.models[0].id;
                            fal.api.image_model(first).cloned()
                        });
                        if let Some(model) = model {
                            this.open_image(model, None, window, cx);
                        }
                    }
                    "video" => {
                        // Without a provider set, the first model fal offers.
                        let model = this.video_model(cx).or_else(|| {
                            let fal = flikk_cloud::provider("fal")?;
                            let first =
                                fal.offer(flikk_core::cloud::Capability::Video)?.models[0].id;
                            fal.api.video_model(first).cloned()
                        });
                        if let Some(model) = model {
                            this.open_video(model, window, cx);
                        }
                    }
                    _ => this.open_generate(generate::Kind::Music, window, cx),
                }
            });
        }
        Self {
            state,
            focus: cx.focus_handle(),
            search,
            bin_input,
            renaming_item: None,
            item_input,
            layout: Layout::Grid,
            bin: None,
            renaming: None,
            sel,
            thumbs: Thumbs::default(),
            jobs: Vec::new(),
            proxies: Arc::default(),
            hdr_proxies: Default::default(),
            dropping: None,
            area: Rc::default(),
            cols: Cell::new(1),
            scroll: ScrollHandle::default(),
            reveal: Rc::default(),
            dragged: Vec::new(),
            skim: None,
            placed: Rc::default(),
            band: None,
            _subscriptions,
            _poll,
        }
    }

    fn poll(&mut self, cx: &mut Context<Self>) {
        let jobs = self
            .state
            .read(cx)
            .services
            .analysis
            .as_ref()
            .map(|a| a.jobs())
            .unwrap_or_default();
        self.refresh_proxies(cx);
        let proxying = !self.proxies.lock().unwrap().is_empty();
        if jobs != self.jobs || proxying {
            self.jobs = jobs;
            cx.notify();
        }
    }

    /// The item's background work, `None` when idle.
    fn progress(&self, id: MediaId) -> Option<Progress> {
        if let Some(f) = self.proxies.lock().unwrap().get(&id) {
            return Some(Progress::Proxy(*f));
        }
        let job = self.jobs.iter().rev().find(|j| j.media == Some(id))?;
        match &job.state {
            JobState::Queued => Some(Progress::Queued),
            JobState::Running { fraction } => Some(Progress::Analyzing(*fraction)),
            JobState::Done => None,
            JobState::Failed { .. } => Some(Progress::Failed),
        }
    }

    /// The item's "Analyze" entry; `None` for images, which are not
    /// analyzed.
    fn analyze_entry(&self, id: MediaId, cx: &App) -> Option<AnalyzeEntry> {
        let state = self.state.read(cx);
        let item = state.bus.project().media(id)?;
        let analysis = state.services.analysis.as_ref()?;
        if item.kind == MediaKind::Image {
            return None;
        }
        let job = self.jobs.iter().rev().find(|j| j.media == Some(id));
        let fp = item.fingerprint.as_ref();
        let script = item.generated.as_deref().and_then(|g| g.script());
        // Results that lack a step are added to; whole ones are replaced.
        let again = analysis.coverage(item) == Coverage::Full;
        Some(match job.map(|j| &j.state) {
            Some(JobState::Queued) => AnalyzeEntry::Queued,
            Some(JobState::Running { .. }) => AnalyzeEntry::Running,
            // A file that could not be read has nothing to analyze.
            _ if fp.is_none() => AnalyzeEntry::Unreadable,
            // A voiceover's script stands in for transcription.
            _ if script.is_none() && !state.models_ready() => AnalyzeEntry::SetUp,
            _ => AnalyzeEntry::Ready { again },
        })
    }

    // ------------------------------------------------------------ actions

    fn analyze(&mut self, id: MediaId, again: bool, cx: &mut Context<Self>) {
        self.state.update(cx, |s, cx| s.analyze(id, again, cx));
        self.poll(cx);
    }

    fn prompt_import(&mut self, cx: &mut Context<Self>) {
        let paths = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: true,
            multiple: true,
            prompt: None,
        });
        cx.spawn(async move |this, cx| {
            if let Ok(Ok(Some(paths))) = paths.await {
                this.update(cx, |this, cx| this.import(paths, this.bin, cx))
                    .ok();
            }
        })
        .detach();
    }

    /// A click on item `id`.
    fn select(&mut self, id: MediaId, open: bool, window: &mut Window, cx: &mut Context<Self>) {
        self.click(Entry::Media(id), open, window, cx)
    }

    /// A click on an item or folder: cmd/ctrl adds or drops it, shift
    /// takes the run from the last one clicked, and a double click opens
    /// it.
    fn click(&mut self, entry: Entry, open: bool, window: &mut Window, cx: &mut Context<Self>) {
        let naming = match entry {
            Entry::Media(id) => self.renaming_item == Some(id),
            Entry::Folder(id) => self.renaming == Some(id),
        };
        if naming {
            // A click in its name field.
            return;
        }
        window.focus(&self.focus, cx);
        let m = window.modifiers();
        if open {
            match entry {
                Entry::Folder(id) => self.open_bin(Some(id), cx),
                Entry::Media(id) => {
                    self.sel.select_one(entry);
                    self.open(id, cx);
                }
            }
            cx.notify();
            return;
        }
        if m.shift
            && let Some(anchor) = self.sel.cursor()
        {
            let order = self.order(cx);
            let at = |e: Entry| order.iter().position(|x| *x == e);
            if let Some((a, b)) = at(anchor).zip(at(entry)) {
                self.sel.set(&order[a.min(b)..=a.max(b)]);
                cx.notify();
                return;
            }
        }
        if m.secondary() {
            self.sel.toggle(entry);
        } else {
            self.sel.select_one(entry);
        }
        cx.notify();
    }

    /// Folders, then items, as the pool shows them.
    fn order(&self, cx: &App) -> Vec<Entry> {
        let folders = self
            .folders(cx)
            .into_iter()
            .map(|(b, _)| Entry::Folder(b.id));
        let items = self
            .visible_items(cx)
            .into_iter()
            .map(|m| Entry::Media(m.id));
        folders.chain(items).collect()
    }

    /// What an action on `entry` applies to: the selection when `entry`
    /// is in it, else `entry` alone. As items and folders.
    fn split_of(&self, entry: Entry) -> (Vec<MediaId>, Vec<BinId>) {
        let entries = self.sel.entries();
        let entries = if entries.contains(&entry) {
            entries
        } else {
            vec![entry]
        };
        let mut media = Vec::new();
        let mut folders = Vec::new();
        for e in entries {
            match e {
                Entry::Media(m) => media.push(m),
                Entry::Folder(f) => folders.push(f),
            }
        }
        (media, folders)
    }

    /// `,` and `.`: edit the selection into the timeline at the
    /// playhead, in pool order.
    fn edit_selected(&mut self, mode: InsertMode, cx: &mut Context<Self>) {
        let Some(first) = self.sel.lead() else {
            return;
        };
        let ids = self.in_pool_order(&self.group_of(first), cx);
        self.state
            .update(cx, |s, cx| s.edit_at_playhead(&ids, mode, cx));
    }

    /// `ids` in the order the pool shows them.
    fn in_pool_order(&self, ids: &[MediaId], cx: &App) -> Vec<MediaId> {
        self.visible_items(cx)
            .iter()
            .map(|m| m.id)
            .filter(|id| ids.contains(id))
            .collect()
    }

    /// Clear the selection, which closes the details.
    fn deselect(&mut self, cx: &mut Context<Self>) {
        if self.sel.reset() {
            cx.notify();
        }
    }

    /// Play a sound; show anything else in the viewer, at the frame the
    /// pointer skims.
    fn open(&mut self, id: MediaId, cx: &mut Context<Self>) {
        let item = self.state.read(cx).bus.project().media(id).cloned();
        let skimmed = self.skim.filter(|(m, _)| *m == id).map(|(_, f)| f);
        match item {
            Some(item) if self.state.read(cx).can_listen(&item) => {
                self.state.update(cx, |s, cx| s.toggle_source(&item, cx));
            }
            Some(item) => self.state.update(cx, |s, cx| {
                s.open_source(id, cx);
                if let Some(f) = skimmed {
                    s.seek_source(&item, f, cx);
                }
            }),
            None => {}
        }
    }

    /// Space: play or pause the selected sound or video from the pool.
    fn play_selected(&mut self, cx: &mut Context<Self>) {
        let Some(item) = self.selected_item(cx) else {
            return;
        };
        let state = self.state.read(cx);
        let playable = match item.kind {
            MediaKind::Audio => state.can_listen(&item),
            MediaKind::Video => state.services.media.is_some() && !state.is_offline(item.id),
            MediaKind::Image => false,
        };
        if playable {
            self.state.update(cx, |s, cx| s.toggle_source(&item, cx));
        } else if item.kind == MediaKind::Image {
            self.state.update(cx, |s, cx| s.open_source(item.id, cx));
        }
    }

    /// What an action on `id` applies to: the selection when `id` is in
    /// it, else `id` alone.
    fn group_of(&self, id: MediaId) -> Vec<MediaId> {
        let selection = self.sel.items();
        if selection.contains(&id) {
            selection
        } else {
            vec![id]
        }
    }

    /// Arrow keys: move the selection `by` places through the folders and
    /// items that show, keeping it in view.
    fn step(&mut self, by: isize, cx: &mut Context<Self>) {
        let order = self.order(cx);
        if order.is_empty() {
            return;
        }
        let from = self.sel.cursor().or(self.sel.lead().map(Entry::Media));
        let at = from.and_then(|c| order.iter().position(|e| *e == c));
        let next = match at {
            Some(at) => (at as isize + by).clamp(0, order.len() as isize - 1) as usize,
            None if by < 0 => order.len() - 1,
            None => 0,
        };
        self.sel.select_one(order[next]);
        self.reveal.set(true);
        cx.notify();
    }

    /// The rows the arrow keys move by: a grid row up or down, one item
    /// in the list.
    fn row_step(&self) -> isize {
        match self.layout {
            Layout::Grid => self.cols.get().max(1) as isize,
            Layout::List => 1,
        }
    }

    fn select_all(&mut self, cx: &mut Context<Self>) {
        let order = self.order(cx);
        self.sel.set(&order);
        cx.notify();
    }

    /// Ask, then remove `ids` from the project together with their clips.
    fn confirm_remove(&mut self, ids: Vec<MediaId>, window: &mut Window, cx: &mut Context<Self>) {
        let state = self.state.read(cx);
        let project = state.bus.project();
        let ids: Vec<MediaId> = ids
            .into_iter()
            .filter(|i| project.media(*i).is_some())
            .collect();
        let title = match ids.as_slice() {
            [] => return,
            [one] => {
                let name = project.media(*one).map(item_name).unwrap_or_default();
                format!("Remove “{name}” from the project?")
            }
            many => format!("Remove {} items from the project?", many.len()),
        };
        let clips: usize = ids.iter().map(|i| state.clips_using(*i).len()).sum();
        let (state, panel) = (self.state.clone(), cx.entity().downgrade());
        window.open_confirm(cx, move |dialog, _, _| {
            let (state, panel, many) = (state.clone(), panel.clone(), ids.len() > 1);
            let ids = ids.clone();
            let dialog =
                dialog
                    .title(title.clone())
                    .destructive()
                    .confirm("Remove", move |_, cx| {
                        state.update(cx, |s, cx| s.remove_media(&ids, cx));
                        let _ = panel.update(cx, |this, cx| {
                            this.sel.remove(&ids, |_| false);
                            cx.notify();
                        });
                        true
                    });
            match (clips, many) {
                (0, _) => dialog,
                (1, false) => dialog.description("Its clip is removed from the timeline too."),
                (n, false) => {
                    dialog.description(format!("Its {n} clips are removed from the timeline too."))
                }
                (1, true) => dialog.description("Their clip is removed from the timeline too."),
                (n, true) => dialog.description(format!(
                    "Their {n} clips are removed from the timeline too."
                )),
            }
        });
    }

    fn update_media(&self, item: MediaItem, cx: &mut Context<Self>) {
        self.state.update(cx, |s, cx| {
            s.execute(Command::UpdateMedia { media: item }, cx);
        });
    }

    /// The selected items to sync when `id` is one of them, reference
    /// first, and whether they hold a recorder and a camera.
    fn sync_group(&self, id: MediaId, cx: &App) -> Option<(Vec<MediaId>, bool)> {
        let all = self.sel.items();
        if all.len() < 2 || !all.contains(&id) {
            return None;
        }
        let project = self.state.read(cx).bus.project();
        let group = flikk_core::sync::pool_order(project, &all);
        if group.len() < 2 {
            return None;
        }
        let kind = |k| {
            group
                .iter()
                .any(|m| project.media(*m).is_some_and(|i| i.kind == k))
        };
        let recorder = kind(MediaKind::Audio) && kind(MediaKind::Video);
        Some((group, recorder))
    }

    fn selected_item(&self, cx: &App) -> Option<MediaItem> {
        let id = self.sel.lead()?;
        self.state.read(cx).bus.project().media(id).cloned()
    }

    /// Name item `id` in the pool; typing replaces the name, an empty
    /// entry keeps it.
    fn start_item_rename(&mut self, id: MediaId, window: &mut Window, cx: &mut Context<Self>) {
        let Some(item) = self.state.read(cx).bus.project().media(id) else {
            return;
        };
        let name = item_name(item);
        self.renaming_item = Some(id);
        self.item_input.update(cx, |i, cx| {
            i.set_value("", window, cx);
            i.set_placeholder(name, window, cx);
            i.focus(window, cx);
        });
        cx.notify();
    }

    /// The pool's name for the item; its file's name drops the rename.
    fn finish_item_rename(&mut self, name: String, window: &mut Window, cx: &mut Context<Self>) {
        let Some(id) = self.renaming_item.take() else {
            return;
        };
        window.focus(&self.focus, cx);
        let item = self.state.read(cx).bus.project().media(id).cloned();
        if let Some(mut item) = item.filter(|_| !name.is_empty()) {
            let name = (name != file_name(&item.path)).then_some(name);
            if item.name != name {
                item.name = name;
                self.update_media(item, cx);
            }
        }
        cx.notify();
    }

    /// Parts of item `id` the timeline uses, as fractions of it.
    fn used_parts(&self, item: &MediaItem, cx: &App) -> Vec<(f32, f32)> {
        let Some(length) = item
            .info
            .as_ref()
            .map(|i| i.duration.0 as f32)
            .filter(|l| *l > 0.)
        else {
            return Vec::new();
        };
        let tl = &self.state.read(cx).bus.project().timeline;
        tl.tracks
            .iter()
            .flat_map(|t| &t.clips)
            .filter(|c| c.media() == Some(item.id))
            .filter_map(|c| {
                let (a, b) = (c.to_source(c.start)?, c.to_source(c.end())?);
                Some((a.0.min(b.0) as f32 / length, a.0.max(b.0) as f32 / length))
            })
            .collect()
    }

    /// The item's name, or its name field while it is renamed.
    fn name_cell(&self, id: MediaId, look: &Look) -> AnyElement {
        if self.renaming_item == Some(id) {
            return div()
                .min_w_0()
                .flex_1()
                .child(Input::new(&self.item_input).small())
                .into_any_element();
        }
        let color = if look.offline { t::WARN } else { t::T1 };
        div()
            .min_w_0()
            .truncate()
            .text_color(color)
            .child(look.name.clone())
            .into_any_element()
    }

    /// Files from outside moved over the items, or off them.
    fn drag_files(
        &mut self,
        ev: &DragMoveEvent<ExternalPaths>,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let over = ev
            .bounds
            .contains(&ev.event.position)
            .then(|| ev.drag(cx).paths().to_vec());
        if over != self.dropping {
            self.dropping = over;
            cx.notify();
        }
    }

    // ------------------------------------------------------------- render

    /// Whether the items shown come from the open folder and every folder
    /// in it, without folders: while searching.
    fn flattened(&self, cx: &App) -> bool {
        !self.search.read(cx).value().trim().is_empty()
    }

    /// The open folder's items, in import order; while searching, the
    /// matches from it and every folder in it.
    fn visible_items(&self, cx: &App) -> Vec<MediaItem> {
        let query = self.search.read(cx).value().trim().to_lowercase();
        let state = self.state.read(cx);
        let project = state.bus.project();
        let tree = BinTree::of(&project.bins);
        let flat = self.flattened(cx);
        project
            .media
            .iter()
            .filter(|m| match (flat, self.bin) {
                (true, None) => true,
                (true, Some(open)) => tree.within(m.bin, open),
                (false, open) => tree.home(m.bin) == open,
            })
            .filter(|m| query.is_empty() || item_name(m).to_lowercase().contains(&query))
            .cloned()
            .collect()
    }

    /// The Edit panel header's actions while the pool shows: generate and
    /// import.
    pub fn header_actions(&self, cx: &mut Context<Self>) -> AnyElement {
        let generate = Button::new("generate")
            .ghost()
            .small()
            .icon(IconName::Clapperboard)
            .tooltip("Generate");
        h_flex()
            .gap(px(2.))
            .children(self.generate_menu(generate, cx))
            .child(
                Button::new("import")
                    .ghost()
                    .small()
                    .icon(IconName::Plus)
                    .tooltip("Import")
                    .on_click(cx.listener(|this, _, _, cx| this.prompt_import(cx))),
            )
            .into_any_element()
    }

    /// `button` opening what a provider can make; `None` when none can.
    fn generate_menu(&self, button: Button, cx: &mut Context<Self>) -> Option<AnyElement> {
        if !self.can_make(cx) {
            return None;
        }
        let panel = cx.entity();
        let menu = button.dropdown_menu(move |menu, _, cx| generate_items(menu, &panel, cx));
        Some(menu.into_any_element())
    }

    /// Whether a provider can make anything.
    fn can_make(&self, cx: &App) -> bool {
        !self.can_generate(cx).is_empty()
            || self.video_model(cx).is_some()
            || self.can_voiceover(cx)
    }

    fn search_row(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let toggle = |id: &'static str, icon: IconName, tip: &'static str, layout: Layout| {
            Button::new(id)
                .ghost()
                .icon(icon)
                .tooltip(tip)
                .selected(self.layout == layout)
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.layout = layout;
                    cx.notify();
                }))
        };
        h_flex()
            .flex_none()
            .gap(px(4.))
            .p(px(8.))
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .child(Input::new(&self.search).search().kbd("/")),
            )
            .child(toggle("grid", IconName::LayoutGrid, "Grid", Layout::Grid))
            .child(toggle("list", IconName::List, "List", Layout::List))
    }

    /// What a tile or row shows of `item`.
    fn look(&mut self, item: &MediaItem, cx: &mut Context<Self>) -> Look {
        let thumb = self.thumbs.get(item, &self.state, cx);
        let state = self.state.read(cx);
        let listening = state.source.as_ref().filter(|p| p.is(item));
        let used = state.clips_using(item.id).len();
        Look {
            thumb,
            name: item_name(item).into(),
            meta: meta(item, used),
            listenable: state.can_listen(item),
            // A video's progress shows in the viewer.
            listening: listening
                .filter(|_| item.kind == MediaKind::Audio)
                .map(|p| p.fraction()),
            progress: self.progress(item.id),
            selected: self.sel.has_item(item.id),
            offline: state.is_offline(item.id),
        }
    }

    /// The tile's or row's "⋯", shown on hover.
    fn more_button(&self, id: MediaId, group: SharedString, cx: &mut Context<Self>) -> Div {
        let panel = cx.entity();
        div()
            .opacity(0.)
            .group_hover(group, |s| s.opacity(1.))
            .child(
                Button::new(ElementId::Name(format!("media-menu-{id}").into()))
                    .ghost()
                    .xsmall()
                    .icon(IconName::Ellipsis)
                    .dropdown_menu(move |menu, window, cx| item_menu(menu, &panel, id, window, cx)),
            )
    }

    fn tile(&mut self, item: &MediaItem, cx: &mut Context<Self>) -> AnyElement {
        let mut look = self.look(item, cx);
        let id = item.id;
        let group = SharedString::from(format!("media-{id}"));
        // The lead item counts the selection, folders too.
        let picked = self.sel.count();
        let multi = (self.sel.lead() == Some(id) && picked > 1).then_some(picked);
        // Skimming: the pointer's place across a video's picture picks
        // the frame.
        let duration = item.info.as_ref().map(|i| i.duration);
        let skimmable = item.kind == MediaKind::Video && !look.offline && duration.is_some();
        let skim = self
            .skim
            .filter(|(m, _)| *m == id && skimmable)
            .map(|(_, f)| f);
        if let Some(f) = skim {
            let slot = (f * thumbs::SKIM_SLOTS as f32) as u32;
            if let Some(image) = self.thumbs.skim(item, slot, &self.state, cx) {
                look.thumb = Some(image);
            }
        }
        let peaks = (item.kind == MediaKind::Audio)
            .then(|| self.thumbs.peaks(item, &self.state, cx))
            .flatten();
        let used = self.used_parts(item, cx);
        let bounds = Rc::new(Cell::new(Bounds::<Pixels>::default()));
        let seen = bounds.clone();
        let mut thumb = thumb_box(&look, item, peaks.as_deref().map(Vec::as_slice))
            .id(ElementId::Name(format!("thumb-{id}").into()))
            .when(look.selected, |d| d.shadow(ring()))
            .child(
                canvas(move |b, _, _| seen.set(b), |_, _, _, _| {})
                    .absolute()
                    .size_full(),
            )
            .when(skimmable, |d| {
                d.on_mouse_move(cx.listener(move |this, ev: &MouseMoveEvent, _, cx| {
                    let b = bounds.get();
                    let f = ((ev.position.x - b.left()) / b.size.width).clamp(0., 1.);
                    this.skim = Some((id, f));
                    cx.notify();
                }))
                .on_hover(cx.listener(move |this, hovered: &bool, _, cx| {
                    if !hovered && this.skim.is_some_and(|(m, _)| m == id) {
                        this.skim = None;
                        cx.notify();
                    }
                }))
            })
            .children(skim.map(|f| {
                div()
                    .absolute()
                    .top_0()
                    .bottom_0()
                    .left(relative(f))
                    .w(px(1.))
                    .bg(t::T1)
            }))
            // What the timeline uses, along the bottom, unless a bar
            // shows progress there.
            .when(look.progress.is_none() && look.listening.is_none(), |d| {
                d.children(used.into_iter().map(|(a, b)| {
                    div()
                        .absolute()
                        .bottom_0()
                        .h(px(2.))
                        .left(relative(a.clamp(0., 1.)))
                        .w(relative((b - a).clamp(0.01, 1.)))
                        .bg(t::OK)
                }))
            })
            // The selection's count takes the corner from the play button.
            .children((look.listenable && multi.is_none()).then(|| {
                div().absolute().top(px(4.)).left(px(4.)).child(listen_dot(
                    format!("listen-{id}"),
                    &self.state,
                    item,
                    px(18.),
                    cx,
                ))
            }))
            .children(multi.map(|n| {
                thumb_badge()
                    .bg(t::AC)
                    .text_color(t::ON_AC)
                    .child(Icon::new(IconName::Check).size(px(9.)))
                    .child(n.to_string())
            }))
            .children(duration.map(|d| {
                // While skimming, where in the item.
                let at = skim.map_or(d, |f| Time((d.0 as f64 * f as f64) as i64));
                duration_chip(at)
            }))
            .child(
                self.more_button(id, group.clone(), cx)
                    .absolute()
                    .top(px(3.))
                    .right(px(3.)),
            );
        if multi.is_none() && !look.listenable {
            thumb = thumb.children(corner_badge(item, look.progress));
        }
        let meta = self.meta_line(&look, id);
        let tile = self
            .item_frame(item, &group, cx)
            .flex()
            .flex_col()
            .min_w_0()
            .text_size(px(11.))
            .child(thumb)
            .child(div().mt(px(4.)).flex().child(self.name_cell(id, &look)))
            .child(meta);
        self.with_menu(tile, id, cx)
    }

    fn row(&mut self, item: &MediaItem, wide: bool, cx: &mut Context<Self>) -> AnyElement {
        let look = self.look(item, cx);
        let id = item.id;
        let group = SharedString::from(format!("media-{id}"));
        let mini = div()
            .relative()
            .flex()
            .flex_none()
            .items_center()
            .justify_center()
            .w(px(36.))
            .h(px(20.))
            .rounded(px(3.))
            .overflow_hidden()
            .bg(thumb_bg(item))
            .map(|d| match (&look.thumb, item.kind) {
                _ if look.offline => {
                    d.child(Icon::new(IconName::Unlink).size(px(11.)).color(t::WARN))
                }
                (Some(image), _) => {
                    d.child(img(image.clone()).size_full().object_fit(ObjectFit::Cover))
                }
                (None, MediaKind::Audio) if look.listenable => d.child(listen_dot(
                    format!("listen-{id}"),
                    &self.state,
                    item,
                    px(16.),
                    cx,
                )),
                (None, MediaKind::Audio) => {
                    d.child(Icon::new(IconName::AudioLines).size(px(11.)).color(t::A))
                }
                (None, MediaKind::Image) => {
                    d.child(Icon::new(IconName::Image).size(px(11.)).color(t::T3))
                }
                (None, MediaKind::Video) => d,
            });
        let bar = look
            .listening
            .map(|f| (f, t::T1))
            .or(look.progress.and_then(Progress::bar));
        let duration = item
            .info
            .as_ref()
            .map_or("—".to_owned(), |i| clock_rounded(i.duration));
        let selected = look.selected;
        let more = self.more_button(id, group.clone(), cx);
        let bin = self.bin_name(item.bin, cx);
        let row = self
            .item_frame(item, &group, cx)
            .h(px(30.))
            .flex()
            .items_center()
            .gap(px(10.))
            .px(px(8.))
            .rounded(t::RADIUS)
            .text_size(px(12.))
            .when(selected, |d| {
                d.bg(t::alpha(t::AC, 0.1))
                    .shadow(inset_ring(t::alpha(t::AC, 0.4)))
            })
            .when(!selected, |d| d.hover(|s| s.bg(t::HV)))
            .child(mini)
            .child(
                h_flex()
                    .flex_1()
                    .min_w_0()
                    .gap(px(8.))
                    .child(self.name_cell(id, &look))
                    .children(bar.map(|(f, color)| bar3(f, color).w(px(40.)).flex_none())),
            )
            .child(column(duration, 56.).font_family(t::mono()))
            .when(wide, |d| {
                let format = if look.offline {
                    column("Offline", 120.).text_color(t::WARN)
                } else {
                    column(format_of(item), 120.)
                };
                d.child(format).child(column(bin, 90.))
            })
            .child(more);
        self.with_menu(row, id, cx)
    }

    /// What tiles and rows share: selecting, opening, dragging and the
    /// right-click menu.
    fn item_frame(
        &self,
        item: &MediaItem,
        group: &SharedString,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let id = item.id;
        // Grabbing a selected item drags the selection, in pool order.
        let drag = match self.dragged.split_first() {
            Some((&first, more)) if self.dragged.contains(&id) => {
                let project = self.state.read(cx).bus.project();
                let name = project.media(first).map(item_name).unwrap_or_default();
                MediaDrag {
                    media: first,
                    name: name.into(),
                    more: more.to_vec(),
                    folders: self.sel.folders().to_vec(),
                }
            }
            _ => MediaDrag::one(id, item_name(item).into()),
        };
        div()
            .id(ElementId::Name(group.clone()))
            .group(group.clone())
            .relative()
            .cursor_pointer()
            .on_click(cx.listener(move |this, ev: &ClickEvent, window, cx| {
                cx.stop_propagation();
                this.select(id, ev.click_count() >= 2, window, cx)
            }))
            .on_drag(drag, |drag, _, _, cx| cx.new(|_| drag.clone()))
            .child(self.place_marker(Entry::Media(id)))
            .when(self.sel.cursor() == Some(Entry::Media(id)), |d| {
                d.child(self.reveal_marker())
            })
    }

    /// Inside an item or folder: notes where it paints, for the rubber
    /// band.
    fn place_marker(&self, item: Entry) -> impl IntoElement {
        let placed = self.placed.clone();
        canvas(
            move |b, _, _| placed.borrow_mut().push((item, b)),
            |_, _, _, _| {},
        )
        .absolute()
        .size_full()
    }

    /// `p` in the items' own space, which scrolls with them.
    fn in_items(&self, p: Point<Pixels>) -> Point<Pixels> {
        p - self.scroll.offset()
    }

    /// Inside the selected item: after an arrow key, scrolls the items so
    /// it shows.
    fn reveal_marker(&self) -> impl IntoElement {
        let (reveal, area, scroll) = (self.reveal.clone(), self.area.clone(), self.scroll.clone());
        canvas(
            move |item, window, _| {
                if !reveal.replace(false) {
                    return;
                }
                let view = area.get();
                let margin = px(8.);
                let mut offset = scroll.offset();
                if item.top() - margin < view.top() {
                    offset.y += view.top() - item.top() + margin;
                } else if item.bottom() + margin > view.bottom() {
                    offset.y -= item.bottom() + margin - view.bottom();
                } else {
                    return;
                }
                scroll.set_offset(offset);
                window.request_animation_frame();
            },
            |_, _, _, _| {},
        )
        .absolute()
        .size_full()
    }

    /// The item's menu on a right click.
    fn with_menu(&self, el: Stateful<Div>, id: MediaId, cx: &mut Context<Self>) -> AnyElement {
        let panel = cx.entity();
        el.context_menu(move |menu, window, cx| item_menu(menu, &panel, id, window, cx))
            .into_any_element()
    }

    /// The tile's second line: the item's format, or what is happening to
    /// it.
    fn meta_line(&self, look: &Look, id: MediaId) -> Stateful<Div> {
        let line = div()
            .id(ElementId::Name(format!("meta-{id}").into()))
            .text_size(px(10.))
            .text_color(t::T3)
            .truncate();
        if look.offline {
            let state = self.state.clone();
            return line.child(
                h_flex().gap(px(3.)).child("Offline ·").child(
                    div()
                        .id(ElementId::Name(format!("relink-{id}").into()))
                        .text_color(t::T2)
                        .hover(|s| s.text_color(t::T1))
                        .child("Relink")
                        .on_click(move |_, _, cx| {
                            cx.stop_propagation();
                            crate::relink::relink_item(&state, id, cx)
                        }),
                ),
            );
        }
        match look.progress {
            Some(Progress::Failed) => line.text_color(t::ERR).child("Analysis failed"),
            Some(Progress::Queued) => line.child("Queued for analysis"),
            Some(Progress::Analyzing(f)) => line.child(format!("Analyzing · {:.0} %", f * 100.)),
            Some(Progress::Proxy(_)) => line.child(format!("{} · proxy building", look.meta)),
            None => line.child(look.meta.clone()),
        }
    }

    fn bin_name(&self, bin: Option<BinId>, cx: &App) -> String {
        bin.and_then(|id| {
            let bins = &self.state.read(cx).bus.project().bins;
            bins.iter().find(|b| b.id == id).map(|b| b.name.clone())
        })
        .unwrap_or_default()
    }

    /// The list's column names, when it is wide enough to have columns.
    fn list_header(&self) -> impl IntoElement {
        h_flex()
            .h(px(24.))
            .gap(px(10.))
            .px(px(8.))
            .text_size(px(10.))
            .text_color(t::T3)
            .child(div().w(px(36.)).flex_none())
            .child(div().flex_1().child("Name"))
            .child(column("Duration", 56.))
            .child(column("Format", 120.))
            .child(column("Folder", 90.))
            .child(div().w(px(20.)).flex_none())
    }

    /// Play and seek for a sound.
    fn listen_bar(&self, item: &MediaItem, cx: &App) -> Option<AnyElement> {
        let state = self.state.read(cx);
        if !state.can_listen(item) {
            return None;
        }
        let source = state.source.as_ref().filter(|p| p.is(item));
        let fraction = source.map_or(0., |p| p.fraction());
        let at = source.map_or(Time::ZERO, |p| p.position());
        let (seeker, sound) = (self.state.clone(), item.clone());
        let bar = seek_bar(
            fraction,
            None,
            move |f, cx| seeker.update(cx, |s, cx| s.seek_source(&sound, f, cx)),
            cx,
        );
        Some(
            h_flex()
                .gap(px(8.))
                .child(listen_dot(
                    "listen-selected",
                    &self.state,
                    item,
                    px(22.),
                    cx,
                ))
                .child(bar)
                .child(
                    div()
                        .font_family(t::mono())
                        .text_size(px(10.))
                        .text_color(t::T3)
                        .child(clock_rounded(at)),
                )
                .into_any_element(),
        )
    }

    fn details(&self, item: &MediaItem, cx: &mut Context<Self>) -> AnyElement {
        let mut lines: Vec<SharedString> = Vec::new();
        if let Some(info) = &item.info {
            let mut head = vec![clock_rounded(info.duration)];
            if let Some(v) = &info.video {
                head.push(format!("{}×{}", v.width, v.height));
                head.push(format!("{:.2} fps", v.rate.fps()).replace(".00", ""));
                head.push(v.codec.clone());
                head.extend(v.hdr.as_ref().map(|h| h.describe()));
            }
            head.extend(file_type(item));
            lines.push(head.join(" · ").into());
            for a in &info.audio {
                let mut parts = vec![format!("A{}", a.index)];
                parts.extend(a.language.clone());
                parts.push(format!("{} ch", a.channels));
                parts.push(format!("{} kHz", a.sample_rate / 1000));
                parts.push(a.codec.clone());
                lines.push(parts.join(" · ").into());
            }
        }
        let id = item.id;
        v_flex()
            .flex_none()
            .gap(px(6.))
            .px(px(10.))
            .py(px(8.))
            .border_t_1()
            .border_color(t::LN)
            .child(
                h_flex()
                    .gap(px(4.))
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .font_weight(FontWeight::MEDIUM)
                            .truncate()
                            .child(item_name(item)),
                    )
                    .child(
                        Button::new("remove-media")
                            .ghost()
                            .xsmall()
                            .icon(IconName::Trash)
                            .tooltip("Remove from project")
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.confirm_remove(vec![id], window, cx)
                            })),
                    ),
            )
            .children(self.listen_bar(item, cx))
            .child(v_flex().gap(px(2.)).children(lines.into_iter().map(|l| {
                div()
                    .text_size(px(11.))
                    .text_color(t::T3)
                    .truncate()
                    .child(l)
            })))
            .into_any_element()
    }

    /// Before the first import: a drop zone with Import and Generate.
    fn empty(&self, cx: &mut Context<Self>) -> AnyElement {
        let generate = Button::new("empty-generate")
            .ghost()
            .icon(IconName::Clapperboard)
            .label("Generate");
        EmptyState::new(IconName::Film, "No media yet")
            .hint("Drop files or folders here")
            .drop_zone()
            .child(
                Button::new("empty-import")
                    .icon(IconName::Download)
                    .label("Import")
                    .on_click(cx.listener(|this, _, _, cx| this.prompt_import(cx))),
            )
            .children(self.generate_menu(generate, cx))
            .into_any_element()
    }

    /// Over the items while files from outside are dragged there.
    fn drop_overlay(&self, paths: &[PathBuf], cx: &App) -> Div {
        let noun = match (paths.len(), paths.iter().any(|p| p.is_dir())) {
            (1, false) => "file",
            (_, false) => "files",
            (1, true) => "folder",
            (_, true) => "items",
        };
        let title = match self.bin {
            Some(_) => format!(
                "Import {} {noun} to {}",
                paths.len(),
                self.bin_name(self.bin, cx)
            ),
            None => format!("Import {} {noun}", paths.len()),
        };
        let mut names: Vec<String> = paths.iter().take(2).map(|p| file_name(p)).collect();
        if paths.len() > 2 {
            names.push(format!("+{}", paths.len() - 2));
        }
        v_flex()
            .absolute()
            .inset(px(6.))
            .items_center()
            .justify_center()
            .gap(px(6.))
            .rounded(px(6.))
            .border_1()
            .border_dashed()
            .border_color(t::AC)
            .bg(t::alpha(t::AC, 0.08))
            .child(
                div()
                    .flex()
                    .items_center()
                    .justify_center()
                    .size(px(30.))
                    .rounded(px(7.))
                    .bg(t::AC_WASH)
                    .child(Icon::new(IconName::Download).size(px(16.)).color(t::AC)),
            )
            .child(div().font_weight(FontWeight::MEDIUM).child(title))
            .child(
                div()
                    .px(px(12.))
                    .max_w_full()
                    .truncate()
                    .font_family(t::mono())
                    .text_size(px(10.))
                    .text_color(t::T2)
                    .child(names.join(" · ")),
            )
    }
}

impl Render for MediaPoolPanel {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if self.dropping.is_some() && !cx.has_active_drag() {
            self.dropping = None;
        }
        let root = v_flex()
            .id("media-pool")
            .size_full()
            .text_size(px(12.))
            .text_color(t::T1)
            .track_focus(&self.focus)
            .key_context("MediaPool")
            .on_action(cx.listener(|this, _: &RemoveSelected, window, cx| {
                let (media, folders) = (this.sel.items(), this.sel.folders().to_vec());
                this.confirm_delete(media, folders, window, cx);
            }))
            .on_action(cx.listener(|this, _: &PlaySelected, _, cx| this.play_selected(cx)))
            .on_action(cx.listener(|this, _: &OpenSelected, _, cx| {
                match this.sel.cursor().filter(|_| this.sel.count() == 1) {
                    Some(Entry::Folder(id)) => this.open_bin(Some(id), cx),
                    _ => {
                        if let Some(id) = this.sel.lead() {
                            this.open(id, cx);
                        }
                    }
                }
            }))
            .on_action(cx.listener(|this, _: &SelectAll, _, cx| this.select_all(cx)))
            .on_action(cx.listener(|this, _: &Deselect, _, cx| this.deselect(cx)))
            .on_action(cx.listener(|this, _: &OpenParentBin, _, cx| {
                let bins = &this.state.read(cx).bus.project().bins;
                let parent = BinTree::of(bins).ancestry(this.bin).nth(1);
                this.open_bin(parent, cx)
            }))
            .on_action(cx.listener(
                |this, _: &RenameSelected, window, cx| match this.sel.cursor() {
                    Some(Entry::Folder(id)) if this.sel.has_folder(id) => {
                        this.start_rename(id, window, cx)
                    }
                    _ => {
                        if let Some(id) = this.sel.lead() {
                            this.start_item_rename(id, window, cx);
                        }
                    }
                },
            ))
            .on_action(cx.listener(|this, _: &MarkSourceIn, _, cx| {
                this.state.update(cx, |s, cx| s.mark_source(false, cx));
            }))
            .on_action(cx.listener(|this, _: &MarkSourceOut, _, cx| {
                this.state.update(cx, |s, cx| s.mark_source(true, cx));
            }))
            .on_action(cx.listener(|this, _: &InsertSelected, _, cx| {
                this.edit_selected(InsertMode::Insert, cx)
            }))
            .on_action(cx.listener(|this, _: &OverwriteSelected, _, cx| {
                this.edit_selected(InsertMode::Overwrite, cx)
            }))
            .on_action(cx.listener(|this, _: &SelectPrev, _, cx| this.step(-1, cx)))
            .on_action(cx.listener(|this, _: &SelectNext, _, cx| this.step(1, cx)))
            .on_action(cx.listener(|this, _: &SelectUp, _, cx| this.step(-this.row_step(), cx)))
            .on_action(cx.listener(|this, _: &SelectDown, _, cx| this.step(this.row_step(), cx)))
            .on_action(cx.listener(|this, _: &FocusSearch, window, cx| {
                this.search.update(cx, |s, cx| s.focus(window, cx));
            }))
            .on_drop(cx.listener(|this, paths: &ExternalPaths, _, cx| {
                this.dropping = None;
                this.import(paths.paths().to_vec(), this.bin, cx)
            }));
        let project = self.state.read(cx).bus.project();
        // Rows of a project closed while they ran show with that project.
        let generating: Vec<_> = (self.state.read(cx).generating.iter())
            .filter(|g| g.project == project.id)
            .cloned()
            .collect();
        if project.media.is_empty() && project.bins.is_empty() && generating.is_empty() {
            return root.child(self.empty(cx));
        }

        // The open bin can go, by undo or by another's hand.
        if self
            .bin
            .is_some_and(|id| !project.bins.iter().any(|b| b.id == id))
        {
            // As `open_bin(None)` does; `project` still borrows `cx`.
            self.bin = None;
            self.sel.reset();
            self.scroll.set_offset(point(px(0.), px(0.)));
        }
        self.placed.borrow_mut().clear();
        let items = self.visible_items(cx);
        let folders = self.folders(cx);
        self.dragged = if self.sel.count() < 2 {
            Vec::new()
        } else {
            let selection = self.sel.items();
            items
                .iter()
                .map(|m| m.id)
                .filter(|id| selection.contains(id))
                .collect()
        };
        let width = self.area.get().size.width.as_f32();
        let wide = width >= WIDE_LIST;
        let content: AnyElement = if items.is_empty() && folders.is_empty() && generating.is_empty()
        {
            let searching = !self.search.read(cx).value().trim().is_empty();
            match searching {
                true => EmptyState::new(IconName::Search, "No matches").compact(),
                false => EmptyState::new(IconName::Inbox, "Nothing in this folder").compact(),
            }
            .into_any_element()
        } else {
            match self.layout {
                Layout::Grid => {
                    let cols = if width > 0. {
                        ((width - 16. + 8.) / (TILE + 8.)).floor().max(1.) as u16
                    } else {
                        2
                    };
                    self.cols.set(cols);
                    let mut tiles: Vec<AnyElement> = folders
                        .iter()
                        .map(|(b, n)| self.folder(b, *n, false, cx))
                        .collect();
                    tiles.extend(generating.iter().map(|g| self.generation_tile(g, cx)));
                    tiles.extend(items.iter().map(|m| self.tile(m, cx)));
                    div()
                        .grid()
                        .grid_cols(cols)
                        .gap_x(px(8.))
                        .gap_y(px(10.))
                        .px(px(8.))
                        .py(px(10.))
                        .children(tiles)
                        .into_any_element()
                }
                Layout::List => {
                    let mut rows: Vec<AnyElement> = folders
                        .iter()
                        .map(|(b, n)| self.folder(b, *n, wide, cx))
                        .collect();
                    rows.extend(generating.iter().map(|g| self.generation_row(g, cx)));
                    rows.extend(items.iter().map(|m| self.row(m, wide, cx)));
                    v_flex()
                        .p(px(4.))
                        .when(wide, |d| d.child(self.list_header()))
                        .children(rows)
                        .into_any_element()
                }
            }
        };
        let measured = self.area.clone();
        let dropping = self.dropping.clone();
        let panel = cx.entity();
        // Details for an item that shows here, not one left in another bin.
        let selected = self
            .selected_item(cx)
            .filter(|item| items.iter().any(|m| m.id == item.id));
        root.child(self.search_row(cx))
            .child(self.path_bar(cx))
            .child(div().flex_none().h(px(1.)).bg(t::LN))
            .child(
                div()
                    .relative()
                    .flex_1()
                    .min_h_0()
                    .on_drag_move(cx.listener(Self::drag_files))
                    .child(
                        canvas(
                            move |b, window, _| {
                                // Columns and the list's layout follow the
                                // width at once, not on the next repaint.
                                if measured.replace(b).size.width != b.size.width {
                                    window.request_animation_frame();
                                }
                            },
                            |_, _, _, _| {},
                        )
                        .absolute()
                        .size_full(),
                    )
                    .child(
                        div()
                            .id("media-items")
                            .size_full()
                            .overflow_y_scroll()
                            .track_scroll(&self.scroll)
                            // A press between items clears the selection;
                            // a drag there draws a rubber band.
                            .on_mouse_down(
                                MouseButton::Left,
                                cx.listener(|this, ev, window, cx| this.band_start(ev, window, cx)),
                            )
                            .on_mouse_move(cx.listener(|this, ev, _, cx| this.band_move(ev, cx)))
                            .on_mouse_up(
                                MouseButton::Left,
                                cx.listener(|this, _, _, cx| this.band_end(cx)),
                            )
                            .on_mouse_up_out(
                                MouseButton::Left,
                                cx.listener(|this, _, _, cx| this.band_end(cx)),
                            )
                            .child(content)
                            .context_menu(move |menu, window, cx| {
                                space_menu(menu, &panel, window, cx)
                            }),
                    )
                    .children(self.band_overlay())
                    .vertical_scrollbar(&self.scroll)
                    .children(dropping.map(|paths| self.drop_overlay(&paths, cx))),
            )
            .children(selected.map(|item| self.details(&item, cx)))
    }
}

/// The "Analyze" entry of an item's menu: what it says about why it
/// cannot run, or where to go so it can.
#[derive(Clone, Copy)]
enum AnalyzeEntry {
    Queued,
    Running,
    Unreadable,
    /// A model it needs is missing: opens where to get it.
    SetUp,
    /// `again` when its results cover every step, which analyzing
    /// replaces; otherwise analyzing adds the steps they lack.
    Ready {
        again: bool,
    },
}

/// Where an item or folder painted.
type Placed = (Entry, Bounds<Pixels>);

/// A folder or an item: what the pool lists and selects.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Entry {
    Folder(BinId),
    Media(MediaId),
}

/// A fixed-width list column.
fn column(text: impl Into<SharedString>, width: f32) -> Div {
    div()
        .w(px(width))
        .flex_none()
        .truncate()
        .text_size(px(11.))
        .text_color(t::T2)
        .child(text.into())
}
